async def start_retry_worker(self):
    """Start background retry worker task."""
    logger.info(f"Starting memory retry worker (interval: {self.RETRY_INTERVAL}s)")
    while True:
        try:
            await asyncio.sleep(self.RETRY_INTERVAL)
            await self.retry_queued_memories()
        except Exception as e:
            logger.error(f"Error in retry worker loop: {str(e)}", exc_info=True)
            await asyncio.sleep(self.RETRY_INTERVAL)

