async def flush_stale_sessions(self): """ Background worker to flush orchestrator buffers for inactive sessions.
Scans all session:* keys and triggers flush for sessions inactive > 10 minutes. This ensures single-message conversations or final messages are not lost. """ start_time = time.time() logger.info("Starting stale session flush worker")
try: async with StateManager() as state_manager: cursor = 0 total_checked = 0 total_flushed = 0
while True: cursor, keys = await state_manager.redis_client.scan( cursor=cursor, match="session:*", count=100 )
for session_key in keys: user_id = session_key.decode('utf-8').replace("session:", "")
# Get session data session_json = await state_manager.redis_client.get(session_key) if not session_json: continue
session = json.loads(session_json) conversation_id = session.get("conversation_id") last_activity = session.get("last_activity")
if not conversation_id or not last_activity: continue
total_checked += 1
# Check if already flushed flush_marker_key = f"flushed:{conversation_id}" already_flushed = await state_manager.redis_client.exists(flush_marker_key) if already_flushed: continue
# Calculate inactivity last_activity_dt = datetime.fromisoformat(last_activity.replace('Z', '+00:00')) now = datetime.now(timezone.utc) inactive_seconds = (now - last_activity_dt).total_seconds()
if inactive_seconds >= self.INACTIVE_THRESHOLD: # Trigger flush logger.info( "Flushing stale session", extra={ "user_id": user_id, "conversation_id": conversation_id, "inactive_seconds": inactive_seconds } )
try: await self.stream_conversation_message( user_id=user_id, conversation_id=conversation_id, role="system", content="", flush=True )
# Mark as flushed to avoid double-flush await state_manager.redis_client.setex( flush_marker_key, self.FLUSH_MARKER_TTL, "1" ) total_flushed += 1
except Exception as e: logger.warning( f"Failed to flush stale session: {str(e)}", extra={ "user_id": user_id, "conversation_id": conversation_id } )
if cursor == 0: break
duration_ms = int((time.time() - start_time) * 1000) logger.info( "Stale session flush worker completed", extra={ "total_checked": total_checked, "total_flushed": total_flushed, "duration_ms": duration_ms } )
except Exception as e: duration_ms = int((time.time() - start_time) * 1000) logger.error( f"Stale session flush worker failed: {str(e)}", extra={"duration_ms": duration_ms}, exc_info=True )

async def start_flush_worker(self): """ Start background flush worker task.
Runs indefinitely, flushing stale sessions every FLUSH_CHECK_INTERVAL seconds. """ logger.info( f"Starting stale session flush worker (interval: {self.FLUSH_CHECK_INTERVAL}s, threshold: {self.INACTIVE_THRESHOLD}s)" )
while True: try: await asyncio.sleep(self.FLUSH_CHECK_INTERVAL) await self.flush_stale_sessions() except Exception as e: logger.error( f"Error in flush worker loop: {str(e)}", exc_info=True ) await asyncio.sleep(self.FLUSH_CHECK_INTERVAL)
